return [{
  json: {
    workflow: 'WF7-Journal Metadata & Quality Enrichment',
    start_ms: Date.now(),
    started_at: new Date().toISOString()
  }
}];

// ======================================================
// Build Completion Summary — WF7
// Mode: Run Once for All Items
// Input: Loop Over Papers → DONE
// ======================================================

// ------------------------------------------------------
// 1. รับผลทั้งหมดจาก Loop
// ------------------------------------------------------
const items = $input.all();

// จำนวน Paper ต้นทางทั้งหมด
const total = $('Get row(s) – Analysis_Master').all().length;

// ------------------------------------------------------
// 2. นับ Include / Exclude
//
// TRUE path:
// หลัง Append Analysis_Master_Include
// จะมี ai_status = pending
//
// FALSE path:
// จะมี screening_decision = Exclude
// ------------------------------------------------------
let included = 0;
let excluded = 0;
let unknown = 0;

for (const item of items) {
  const data = item.json || {};

  const decision = String(
    data.screening_decision ?? ''
  ).trim().toLowerCase();

  const aiStatus = String(
    data.ai_status ?? ''
  ).trim().toLowerCase();

  // TRUE path
  if (
    decision === 'include' ||
    aiStatus === 'pending'
  ) {
    included++;
    continue;
  }

  // FALSE path
  if (decision === 'exclude') {
    excluded++;
    continue;
  }

  // กรณีผิดปกติ
  unknown++;
}

// ------------------------------------------------------
// 3. อ่านเวลาเริ่มต้นจาก Set Execution Start
// ------------------------------------------------------
const startData =
  $('Set Execution Start').first().json || {};

let startMs = Number(
  startData.start_ms ??
  startData.started_ms ??
  startData.start_time_ms ??
  0
);

// fallback ถ้าไม่มี milliseconds
if (!startMs) {
  const startString =
    startData.started_at ??
    startData.start_time ??
    startData.execution_start ??
    '';

  const parsed = Date.parse(startString);

  if (!Number.isNaN(parsed)) {
    startMs = parsed;
  }
}

// ------------------------------------------------------
// 4. เวลาสิ้นสุด / Duration
// ------------------------------------------------------
const finishedMs = Date.now();

const durationMs =
  startMs > 0
    ? Math.max(0, finishedMs - startMs)
    : 0;

const durationSeconds =
  Math.round(durationMs / 1000);

const minutes =
  Math.floor(durationSeconds / 60);

const seconds =
  durationSeconds % 60;

const durationText =
  minutes > 0
    ? `${minutes} นาที ${seconds} วินาที`
    : `${seconds} วินาที`;

// ------------------------------------------------------
// 5. Format เวลา Thailand
// ใช้ Gregorian calendar เพื่อให้ปีแสดงเป็น 2026
// ------------------------------------------------------
const formatBangkokTime = (timestamp) => {
  if (!timestamp) {
    return '-';
  }

  return new Date(timestamp).toLocaleString(
    'th-TH-u-ca-gregory',
    {
      timeZone: 'Asia/Bangkok',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false
    }
  );
};

const startedAt =
  startMs > 0
    ? formatBangkokTime(startMs)
    : '-';

const finishedAt =
  formatBangkokTime(finishedMs);

// ------------------------------------------------------
// 6. Execution ID
// ------------------------------------------------------
const executionId =
  String($execution.id ?? '-');

// ------------------------------------------------------
// 7. URL Analysis_Master_Include
// ------------------------------------------------------
const analysisMasterIncludeUrl =
  String(
    startData.analysis_master_include_url ?? ''
  ).trim();

// ------------------------------------------------------
// 8. ตรวจสอบผล
// ------------------------------------------------------
const screened =
  included + excluded;

const completionPercent =
  total > 0
    ? Math.round((screened / total) * 100)
    : 0;

const includePercent =
  total > 0
    ? Math.round((included / total) * 100)
    : 0;

// ------------------------------------------------------
// 9. Output → Build LINE Flex
// ------------------------------------------------------
return [
  {
    json: {
      workflow: 'WF7',

      total,
      included,
      excluded,

      unknown,
      screened,

      completion_percent: completionPercent,
      include_percent: includePercent,

      duration_ms: durationMs,
      duration_seconds: durationSeconds,
      duration_minutes:
        Number((durationSeconds / 60).toFixed(2)),

      duration_text: durationText,

      started_at: startedAt,
      finished_at: finishedAt,

      execution_id: executionId,

      analysis_master_include_url:
        analysisMasterIncludeUrl
    }
  }
];

// ======================================================
// Code | Build LINE Flex — WF7 Screening
// Mode: Run Once for Each Item
// Input: Build Completion Summary
// Theme: Pink / Compact
// ======================================================

const data = $json;

// ------------------------------------------------------
// 1. อ่านข้อมูลสรุปผล WF7
// ------------------------------------------------------
const total = Number(
  data.total ?? 0
);

const included = Number(
  data.included ?? 0
);

const excluded = Number(
  data.excluded ?? 0
);

const unknown = Number(
  data.unknown ?? 0
);

const durationText = String(
  data.duration_text || '-'
);

const startedAt = String(
  data.started_at || '-'
);

const finishedAt = String(
  data.finished_at || '-'
);

const executionId = String(
  data.execution_id || '-'
);

const includeSheetUrl = String(
  data.analysis_master_include_url || ''
).trim();

// ------------------------------------------------------
// 2. อ่านค่าที่ Summary คำนวณไว้แล้ว
// ------------------------------------------------------
const screened = Number(
  data.screened ?? (included + excluded)
);

const completionPercent = Number(
  data.completion_percent ??
  (
    total > 0
      ? Math.round((screened / total) * 100)
      : 0
  )
);

const includePercent = Number(
  data.include_percent ??
  (
    total > 0
      ? Math.round((included / total) * 100)
      : 0
  )
);

// ------------------------------------------------------
// 3. Theme
// ------------------------------------------------------
const pink = '#EC4899';
const pinkDark = '#DB2777';
const pinkLight = '#FDF2F8';

// ------------------------------------------------------
// 4. กำหนดสถานะ
// ------------------------------------------------------
let statusTitle =
  'คัดกรองบทความเสร็จสมบูรณ์';

let statusIcon = '✅';

let headerColor = pink;

let statusDetail =
  `คัดกรองครบ ${screened}/${total} เรื่อง และพร้อมส่ง ${included} เรื่องไปยัง WF8`;

if (total === 0) {

  statusTitle =
    'ไม่พบบทความสำหรับคัดกรอง';

  statusIcon = 'ℹ️';
  headerColor = '#64748B';

  statusDetail =
    'ไม่พบรายการใน Analysis_Master';

} else if (
  unknown > 0 ||
  screened < total
) {

  statusTitle =
    'คัดกรองเสร็จสิ้นบางส่วน';

  statusIcon = '⚠️';
  headerColor = '#F59E0B';

  statusDetail =
    `ประมวลผล ${screened}/${total} เรื่อง และมีรายการต้องตรวจสอบ ${unknown} เรื่อง`;
}

// ------------------------------------------------------
// 5. ฟังก์ชันสร้าง Metric Row
// ------------------------------------------------------
function metricRow(
  label,
  value,
  color = '#111827'
) {

  return {
    type: 'box',
    layout: 'horizontal',
    spacing: 'sm',

    contents: [

      {
        type: 'text',
        text: label,
        size: 'xs',
        color: '#64748B',
        flex: 4,
        wrap: true
      },

      {
        type: 'text',
        text: String(value),
        size: 'xs',
        color,
        weight: 'bold',
        align: 'end',
        flex: 2,
        wrap: true
      }

    ]
  };
}

// ------------------------------------------------------
// 6. สร้าง LINE Flex Bubble
// ------------------------------------------------------
const bubble = {

  type: 'bubble',
  size: 'mega',

  // ----------------------------------------------------
  // HEADER
  // ----------------------------------------------------
  header: {

    type: 'box',
    layout: 'vertical',
    backgroundColor: headerColor,
    paddingAll: '16px',
    spacing: 'xs',

    contents: [

      {
        type: 'text',
        text:
          `${statusIcon} ${statusTitle}`,
        color: '#FFFFFF',
        weight: 'bold',

        // ลดจาก xl → lg
        size: 'lg',

        wrap: true
      },

      {
        type: 'text',
        text: statusDetail,
        color: '#FFF1F7',

        // ลดจาก sm → xs
        size: 'xs',

        wrap: true
      }

    ]
  },

  // ----------------------------------------------------
  // BODY
  // ----------------------------------------------------
  body: {

    type: 'box',
    layout: 'vertical',
    paddingAll: '16px',
    spacing: 'sm',

    contents: [

      {
        type: 'text',
        text: '📚 WF7 • Paper Screening',
        weight: 'bold',

        // ลดจาก md → sm
        size: 'sm',

        color: '#111827',
        wrap: true
      },

      {
        type: 'text',
        text:
          `${completionPercent}% ประมวลผลครบ`,
        weight: 'bold',

        // ลดจาก xxl → xl
        size: 'xl',

        color: pinkDark,
        wrap: true
      },

      {
        type: 'text',
        text:
          `ผ่านการคัดกรอง ${includePercent}%`,
        size: 'xs',
        color: '#64748B',
        wrap: true
      },

      {
        type: 'separator',
        color: '#F3E8EE',
        margin: 'sm'
      },

      // ------------------------------------------------
      // Screening Metrics
      // ------------------------------------------------
      {
        type: 'text',
        text: 'ผลการคัดกรอง',
        weight: 'bold',
        size: 'xs',
        color: '#374151',
        wrap: true
      },

      metricRow(
        '📄 บทความทั้งหมด',
        `${total} เรื่อง`,
        '#111827'
      ),

      metricRow(
        '✅ Include',
        `${included} เรื่อง`,
        '#16A34A'
      ),

      metricRow(
        '❌ Exclude',
        `${excluded} เรื่อง`,
        '#DC2626'
      ),

      ...(unknown > 0
        ? [
            metricRow(
              '⚠️ ตรวจสอบเพิ่มเติม',
              `${unknown} เรื่อง`,
              '#F59E0B'
            )
          ]
        : []),

      {
        type: 'separator',
        color: '#F3E8EE',
        margin: 'sm'
      },

      // ------------------------------------------------
      // เวลา
      // ------------------------------------------------
      {
        type: 'box',
        layout: 'vertical',
        spacing: 'xs',

        contents: [

          {
            type: 'text',
            text:
              `⏱️ ระยะเวลา: ${durationText}`,
            size: 'xs',
            color: '#374151',
            weight: 'bold',
            wrap: true
          },

          {
            type: 'text',
            text:
              `🟢 เริ่ม: ${startedAt}`,
            size: 'xxs',
            color: '#6B7280',
            wrap: true
          },

          {
            type: 'text',
            text:
              `🏁 เสร็จ: ${finishedAt}`,
            size: 'xxs',
            color: '#6B7280',
            wrap: true
          }

        ]
      },

      {
        type: 'text',
        text:
          `Execution ID: ${executionId}`,
        size: 'xxs',
        color: '#9CA3AF',
        wrap: true,
        margin: 'xs'
      },

      // ------------------------------------------------
      // Handoff WF8
      // ------------------------------------------------
      {
        type: 'box',
        layout: 'vertical',
        backgroundColor: pinkLight,
        cornerRadius: '8px',
        paddingAll: '10px',
        margin: 'sm',

        contents: [

          {
            type: 'text',
            text:
              `➡️ พร้อมส่งต่อ WF8: ${included} เรื่อง`,
            size: 'xs',
            color: pinkDark,
            weight: 'bold',
            wrap: true
          }

        ]
      }

    ]
  }

};

// ------------------------------------------------------
// 7. ปุ่มเปิด Analysis_Master_Include
// ------------------------------------------------------
if (/^https?:\/\//i.test(includeSheetUrl)) {

  bubble.footer = {

    type: 'box',
    layout: 'vertical',
    spacing: 'xs',
    paddingAll: '12px',

    contents: [

      {
        type: 'button',
        style: 'primary',
        height: 'sm',

        // ปุ่มสีชมพู
        color: pinkDark,

        action: {
          type: 'uri',
          label:
            'เปิด Analysis_Master_Include',
          uri: includeSheetUrl,

          altUri: {
            desktop: includeSheetUrl
          }
        }
      },

      {
        type: 'text',
        text:
          'Google Sheets • Analysis_Master_Include',
        size: 'xxs',
        color: '#9CA3AF',
        align: 'center',
        margin: 'sm'
      }

    ]
  };

  bubble.styles = {
    ...(bubble.styles || {}),

    footer: {
      separator: true
    }
  };
}

// ------------------------------------------------------
// 8. Alt Text
// ------------------------------------------------------
const altText =
  total > 0
    ? `${statusIcon} WF7 Screening: Include ${included}/${total} เรื่อง`
    : `${statusIcon} WF7 Screening: ไม่พบบทความ`;

// ------------------------------------------------------
// 9. สร้าง Flex Message
// ------------------------------------------------------
const lineMessage = {

  type: 'flex',
  altText,
  contents: bubble

};

// ------------------------------------------------------
// 10. Output
// ------------------------------------------------------
return {

  json: {

    ...data,

    // สำหรับ LineMessageNode-Flex
    line_flex_alt_text:
      altText,

    line_flex_contents:
      bubble,

    line_flex_contents_json:
      JSON.stringify(bubble),

    // Alias รองรับ Node เดิม
    alt_text:
      altText,

    flex_content_json:
      JSON.stringify(bubble),

    // Message พร้อมส่ง
    line_message:
      lineMessage,

    message:
      lineMessage,

    messages:
      [lineMessage]

  }

};

parameters.jsonBody:
={{
  {
    to: $json.toId,
    messages: [
      {
        type: "flex",
        altText: $json.line_flex_alt_text,
        contents:
          typeof $json.line_flex_contents_json === "string"
            ? JSON.parse($json.line_flex_contents_json)
            : $json.line_flex_contents_json
      }
    ]
  }
}}
